#!/usr/bin/env bash
# step201 — dark-theme the order emails (Stripe-clean on the site's dark theme) and
# re-send the test through the REAL path so the inbox gets the dark email WITH the two
# PDFs attached (Invoice + Receipt). PDFs (lib/pdfdocs.js) already exist, unchanged.
set -uo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
TO="${1:-ishtiaqmails@gmail.com}"
cd "$GSZ" || { echo "FATAL: no $GSZ"; exit 1; }

cp -p lib/emails.js "lib/emails.js.bak-step201-$TS"
echo "backup: lib/emails.js.bak-step201-$TS"
restore(){ echo "!! restoring emails.js"; [ -f "lib/emails.js.bak-step201-$TS" ] && cp -p "lib/emails.js.bak-step201-$TS" lib/emails.js; }
trap 'restore' ERR

base64 -d > lib/emails.js <<'EEOF'

EEOF
node --check lib/emails.js || { echo 'EMAILS.JS SYNTAX FAIL'; restore; exit 2; }
grep -q '#060810' lib/emails.js || { echo 'VERIFY FAILED: dark email not written'; restore; exit 3; }
echo "verify ok: dark email written"

trap - ERR
pm2 restart gsz --update-env >/dev/null 2>&1 || pm2 restart gsz >/dev/null 2>&1
ok=0
for i in $(seq 1 25); do
  code=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
  if [ "$code" = "200" ]; then ok=1; echo "health ok (HTTP 200) after ${i} tries"; break; fi
  sleep 0.6
done
[ "$ok" = "1" ] || { echo "HEALTH CHECK FAILED (last: ${code:-none})"; exit 4; }

# --- send ONE test: dark email + Invoice + Receipt PDFs (real path) ---
SJS=$(mktemp /tmp/send201.XXXXXX.js)
base64 -d > "$SJS" <<'SEOF'

SEOF
NODE_PATH="$GSZ/node_modules" node "$SJS" "$TO"
echo "STEP201 DONE."
